SELECT CDSCode
FROM frpm
WHERE `Enrollment (K-12)` + `Enrollment (Ages 5-17)` > 500;

SELECT COUNT(DISTINCT UserId) AS NumUsers
FROM badges
WHERE Name = 'Announcer';

SELECT DisplayName, Age
FROM users
WHERE Views = (SELECT MAX(Views) FROM users);

SELECT LastEditDate, LastEditorUserId
FROM posts
WHERE Title = 'Detecting a given face in a database of facial images';

SELECT OwnerUserId
FROM posts
WHERE FavoriteCount = (SELECT MAX(FavoriteCount) FROM posts);

SELECT Id
FROM users
WHERE Age = (SELECT MIN(Age) FROM users);

SELECT DisplayName
FROM users
WHERE Reputation = (SELECT MAX(Reputation) FROM users);

SELECT Id, Title
FROM posts
WHERE Score = (SELECT MAX(Score) FROM posts);

SELECT COUNT(*) 
FROM posts 
WHERE ViewCount > (SELECT AVG(ViewCount) FROM posts);

SELECT COUNT(*) AS CommentCount
FROM comments
WHERE PostId = (SELECT Id FROM posts WHERE Score = (SELECT MAX(Score) FROM posts));

SELECT Reputation, Views
FROM users
WHERE DisplayName = 'Jarrod Dixon';

SELECT
  (SELECT COUNT(*)
   FROM comments c
   WHERE c.PostId IN (SELECT p.Id FROM posts p WHERE p.Title = 'Clustering 1D data')
  ) AS comment_count,
  (SELECT COUNT(*)
   FROM posts a
   WHERE a.PostTypeId = 2
     AND a.ParentId IN (SELECT p.Id FROM posts p WHERE p.Title = 'Clustering 1D data')
  ) AS answer_count;

SELECT COUNT(CASE WHEN Currency = 'EUR' THEN 1 END) * 100.0 / COUNT(*) AS percentage
FROM customers
WHERE Segment = 'KAM';

SELECT SUM(Amount * Price) 
FROM transactions_1k 
WHERE CustomerID = 38508 AND Date = '201201';

SELECT player_api_id
FROM Player_Attributes
WHERE overall_rating = (SELECT MAX(overall_rating) FROM Player_Attributes);
